import React, { useState, useMemo } from 'react';

function BookingList({ bookings, onCancel }) {
  const [searchUser, setSearchUser]   = useState('');
  const [filterEvent, setFilterEvent] = useState('');
  const [sortOrder, setSortOrder]     = useState('newest');

  // Unique event names for the dropdown
  const eventOptions = useMemo(() => {
    const names = [...new Set(bookings.map((b) => b.eventName))].sort();
    return names;
  }, [bookings]);

  // Apply search + filter + sort
  const filtered = useMemo(() => {
    let result = [...bookings];

    if (searchUser.trim()) {
      const q = searchUser.trim().toLowerCase();
      result = result.filter((b) => b.user_name.toLowerCase().includes(q));
    }

    if (filterEvent) {
      result = result.filter((b) => b.eventName === filterEvent);
    }

    result.sort((a, b) => {
      const diff = new Date(a.booking_date) - new Date(b.booking_date);
      return sortOrder === 'newest' ? -diff : diff;
    });

    return result;
  }, [bookings, searchUser, filterEvent, sortOrder]);

  const clearFilters = () => {
    setSearchUser('');
    setFilterEvent('');
    setSortOrder('newest');
  };

  const hasActiveFilter = searchUser || filterEvent || sortOrder !== 'newest';

  return (
    <div style={{ marginTop: '30px' }}>
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10px' }}>
        <h2 style={{ margin: 0 }}>
          All Bookings
          <span style={{
            marginLeft: '10px', fontSize: '14px', fontWeight: 'normal',
            background: '#e0e0e0', borderRadius: '12px', padding: '2px 10px'
          }}>
            {filtered.length} / {bookings.length}
          </span>
        </h2>
        {hasActiveFilter && (
          <button
            onClick={clearFilters}
            style={{ padding: '4px 12px', cursor: 'pointer', fontSize: '13px' }}
          >
            ✕ Clear filters
          </button>
        )}
      </div>

      {/* Search & Filter Bar */}
      <div style={{
        display: 'flex', gap: '10px', flexWrap: 'wrap',
        padding: '12px', background: '#f8f8f8',
        border: '1px solid #ddd', borderRadius: '6px', marginBottom: '10px'
      }}>
        {/* Search by user name */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '3px' }}>
          <label style={{ fontSize: '12px', color: '#555' }}>Search by name</label>
          <input
            type="text"
            placeholder="e.g. Alice"
            value={searchUser}
            onChange={(e) => setSearchUser(e.target.value)}
            style={{ padding: '6px 10px', border: '1px solid #ccc', borderRadius: '4px', width: '180px' }}
          />
        </div>

        {/* Filter by event */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '3px' }}>
          <label style={{ fontSize: '12px', color: '#555' }}>Filter by event</label>
          <select
            value={filterEvent}
            onChange={(e) => setFilterEvent(e.target.value)}
            style={{ padding: '6px 10px', border: '1px solid #ccc', borderRadius: '4px', width: '200px' }}
          >
            <option value="">All events</option>
            {eventOptions.map((name) => (
              <option key={name} value={name}>{name}</option>
            ))}
          </select>
        </div>

        {/* Sort order */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '3px' }}>
          <label style={{ fontSize: '12px', color: '#555' }}>Sort by date</label>
          <select
            value={sortOrder}
            onChange={(e) => setSortOrder(e.target.value)}
            style={{ padding: '6px 10px', border: '1px solid #ccc', borderRadius: '4px', width: '150px' }}
          >
            <option value="newest">Newest first</option>
            <option value="oldest">Oldest first</option>
          </select>
        </div>
      </div>

      {/* Table */}
      {bookings.length === 0 ? (
        <p>No bookings found.</p>
      ) : filtered.length === 0 ? (
        <p style={{ color: '#888', fontStyle: 'italic' }}>
          No bookings match your search. <button onClick={clearFilters} style={{ cursor: 'pointer' }}>Clear filters</button>
        </p>
      ) : (
        <table border="1" cellPadding="8" cellSpacing="0"
          style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead style={{ backgroundColor: '#f0f0f0' }}>
            <tr>
              <th>Booking ID</th>
              <th>Event ID</th>
              <th>Event Name</th>
              <th>Booked By</th>
              <th>Booked At</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {filtered.map((booking) => (
              <tr key={booking.id}>
                <td>{booking.id}</td>
                <td>{booking.event_id}</td>
                <td>{booking.eventName}</td>
                <td>
                  {/* Highlight search match */}
                  {searchUser.trim()
                    ? highlightMatch(booking.user_name, searchUser.trim())
                    : booking.user_name}
                </td>
                <td>{new Date(booking.booking_date).toLocaleString()}</td>
                <td>
                  <button
                    onClick={() => onCancel(booking.id)}
                    style={{
                      padding: '4px 10px', backgroundColor: '#f44336',
                      color: 'white', border: 'none', cursor: 'pointer', borderRadius: '3px'
                    }}
                  >
                    Cancel
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

// Highlights the matched portion of text in yellow
function highlightMatch(text, query) {
  const idx = text.toLowerCase().indexOf(query.toLowerCase());
  if (idx === -1) return text;
  return (
    <>
      {text.slice(0, idx)}
      <mark style={{ backgroundColor: '#fff176', padding: 0 }}>
        {text.slice(idx, idx + query.length)}
      </mark>
      {text.slice(idx + query.length)}
    </>
  );
}

export default BookingList;
